"use client";

import {
  motion,
  useReducedMotion,
  useScroll,
  useTransform,
  type MotionStyle,
  type MotionValue,
  type Transition,
  type Variants,
} from "motion/react";
import { type ReactNode, type RefObject, useRef } from "react";

import { cn } from "@/lib/utils";

/** Props for a block that fades in from a blur the first time it scrolls into view. */
export interface ScrollRevealProps {
  children: ReactNode;
  /** Seconds to wait, so blocks in a row arrive one after another. Keep it under 0.3. */
  delay?: number;
  /** The element that scrolls, when it is not the page. */
  root?: RefObject<HTMLElement | null>;
  className?: string;
}

/** Props for a line of text that reveals as it scrolls into view. */
export interface ScrollRevealTextProps {
  text: string;
  /** `words` sharpens each word as you scroll. `lines` flies each line up into place; mark lines with a newline. */
  effect?: "words" | "lines";
  /** The element that scrolls, when it is not the page. Give it `relative`, so the scroll can be measured. */
  root?: RefObject<HTMLElement | null>;
  className?: string;
}

const ARRIVE: Transition = { duration: 0.6, ease: [0.19, 1, 0.22, 1] };
// Unread words stay this visible, so the text can always be read ahead of the scroll.
const WORD_FLOOR = 0.2;
// The reveal starts when the text's top is 90% down the view and ends when it is 40% down.
const WORD_RANGE = ["start 0.9", "start 0.4"] as const;

const LINES: Variants = { hidden: {}, shown: { transition: { staggerChildren: 0.08 } } };
const LINE: Variants = { hidden: { y: "110%" }, shown: { y: "0%", transition: ARRIVE } };

/**
 * Fades a block in from a light blur the first time it scrolls into view.
 * With reduced motion it is simply there.
 */
export function ScrollReveal({ children, delay = 0, root, className }: ScrollRevealProps) {
  const reduceMotion = useReducedMotion();
  if (reduceMotion) return <div className={className}>{children}</div>;

  return (
    <motion.div
      className={className}
      initial={{ opacity: 0, y: "1rem", filter: "blur(0.375rem)" }}
      whileInView={{ opacity: 1, y: "0rem", filter: "blur(0rem)" }}
      viewport={{ once: true, amount: 0.4, root }}
      transition={{ ...ARRIVE, delay }}
    >
      {children}
    </motion.div>
  );
}

function Word({ word, index, count, progress }: { word: string; index: number; count: number; progress: MotionValue<number> }) {
  // Each word owns its own slice of the scroll, so the focus moves across the line.
  const start = index / count;
  const end = (index + 1) / count;
  const opacity = useTransform(progress, [start, end], [WORD_FLOOR, 1]);
  const blur = useTransform(progress, [start, end], [0.25, 0]);
  const blurLength = useTransform(blur, (value) => `${value}rem`);
  return (
    <motion.span
      // SAFETY: motion writes motion values into CSS custom properties; MotionStyle only lacks custom keys in its type.
      style={{ "--word-opacity": opacity, "--word-blur": blurLength } as MotionStyle}
      className="opacity-(--word-opacity) blur-(--word-blur)"
    >
      {word}{" "}
    </motion.span>
  );
}

function Words({ text, root, className }: Omit<ScrollRevealTextProps, "effect">) {
  const target = useRef<HTMLParagraphElement>(null);
  const { scrollYProgress } = useScroll({ target, container: root, offset: [...WORD_RANGE] });
  const words = text.split(/\s+/).filter(Boolean);

  return (
    <p ref={target} className={className}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">
        {words.map((word, index) => (
          <Word key={`${word}-${index}`} word={word} index={index} count={words.length} progress={scrollYProgress} />
        ))}
      </span>
    </p>
  );
}

/**
 * Reveals a heading or a short passage as it scrolls into view. `words` brings
 * each word from faint and soft to sharp, tied to the scroll. `lines` flies
 * each line up from behind a mask, once. Screen readers read the whole text,
 * and with reduced motion it is shown as plain text.
 */
export function ScrollRevealText({ text, effect = "words", root, className }: ScrollRevealTextProps) {
  const reduceMotion = useReducedMotion();
  if (reduceMotion) return <p className={cn("whitespace-pre-line", className)}>{text}</p>;
  if (effect === "words") return <Words text={text} root={root} className={className} />;

  return (
    <motion.p
      className={className}
      initial="hidden"
      whileInView="shown"
      viewport={{ once: true, amount: 0.6, root }}
      variants={LINES}
    >
      <span className="sr-only">{text}</span>
      {text.split("\n").map((line, index) => (
        // The mask clips each line, so it rises into place rather than sliding over the one above.
        <span key={`${line}-${index}`} aria-hidden="true" className="block overflow-hidden pb-1">
          <motion.span variants={LINE} className="block">
            {line}
          </motion.span>
        </span>
      ))}
    </motion.p>
  );
}
